interface Auditable {
    void logAudit(String event, String status);
}

interface Retryable {
    int getMaxRetries();
    default boolean retryOperation(java.util.function.BooleanSupplier action) {
        int attempts = 0;
        while (attempts < getMaxRetries()) {
            attempts++;
            if (action.getAsBoolean()) return true;
        }
        return false;
    }
}

abstract class AbstractNotificationChannel implements Auditable {
    protected String channelId;
    protected String destination;

    public AbstractNotificationChannel(String channelId, String destination) {
        this.channelId = channelId;
        this.destination = destination;
    }

    // Template method: Orchestrates notification dispatch and audit logging
    public final boolean send(String message) {
        logAudit("DISPATCH_START", "Destination: " + destination);
        boolean success = sendPayload(message);
        logAudit("DISPATCH_FINISH", success ? "SUCCESS" : "FAILED");
        return success;
    }

    // Abstract customization step
    protected abstract boolean sendPayload(String message);

    @Override
    public void logAudit(String event, String status) {
        System.out.println("[" + channelId + " AUDIT] " + event + " -> " + status);
    }
}

class EmailChannel extends AbstractNotificationChannel implements Retryable {
    public EmailChannel(String channelId, String email) { super(channelId, email); }

    @Override
    public int getMaxRetries() { return 3; }

    @Override
    protected boolean sendPayload(String message) {
        System.out.println("[SMTP Server] Sending email to " + destination + ": " + message);
        return true;
    }
}

public class ChannelDemo {
    public static void main(String[] args) {
        AbstractNotificationChannel email = new EmailChannel("CH-EMAIL-01", "support@corp.com");
        email.send("System database backup completed.");
    }
}

