interface Retryable {
    int getMaxRetries();
}

abstract class BaseChannel {
    protected String dest;
    public BaseChannel(String dest) {
        this.dest = dest;
    }
    public abstract boolean deliver(String msg);
}

class PushChannel extends BaseChannel implements Retryable {
    private int simulatedFailures = 1;
    public PushChannel(String dest) {
        super(dest);
    }
    @Override
    public int getMaxRetries() {
        return 3;
    }
    @Override
    public boolean deliver(String msg) {
        for (int attempt = 1; attempt <= getMaxRetries(); attempt++) {
            if (simulatedFailures > 0) {
                System.out.println("[Push to " + dest + "] Attempt " + attempt + " failed; retrying...");
                simulatedFailures--;
            } else {
                System.out.println("[Push to " + dest + "] Delivered: " + msg);
                return true;
            }
        }
        return false;
    }
}

public class PushApp {
    public static void main(String[] args) {
        PushChannel push = new PushChannel("device-tok-991");
        push.deliver("New Direct Message");
    }
}

interface RateLimited {
    int getLimitPerMinute();
}

abstract class WebhookEndpoint implements RateLimited {
    protected String endpointUrl;
    public WebhookEndpoint(String endpointUrl) {
        this.endpointUrl = endpointUrl;
    }
    public abstract void post(String payload);
}

class SlackWebhook extends WebhookEndpoint {
    private int postCount = 0;
    public SlackWebhook(String url) {
        super(url);
    }
    @Override
    public int getLimitPerMinute() {
        return 2;
    }
    @Override
    public void post(String payload) {
        postCount++;
        if (postCount > getLimitPerMinute()) {
            System.out.println("[Slack] Rejected: Rate limit exceeded (" + getLimitPerMinute() + "/min)");
        } else {
            System.out.println("[Slack POST to " + endpointUrl + "] " + payload);
        }
    }
}

public class SlackApp {
    public static void main(String[] args) {
        WebhookEndpoint slack = new SlackWebhook("https://slack.com/hook");
        slack.post("Msg 1");
        slack.post("Msg 2");
        slack.post("Msg 3");
    }
}

