interface Auditable {
    void audit(String status);
}

abstract class BaseChannel implements Auditable {
    protected String channelType;
    protected String target;
    public BaseChannel(String channelType, String target) {
        if (channelType == null || target == null) throw new IllegalArgumentException();
        this.channelType = channelType;
        this.target = target;
    }
    public final void broadcast(String message) {
        audit("START");
        deliver(message);
        audit("SUCCESS");
    }
    protected abstract void deliver(String message);
    @Override
    public void audit(String status) {
        System.out.println("[" + channelType + " -> " + target + "] Audit: " + status);
    }
}

class SmsNotification extends BaseChannel {
    public SmsNotification(String target) {
        super("SMS", target);
    }
    @Override
    protected void deliver(String message) {
        System.out.println("[" + target + "] SMS: " + message);
    }
}

class DiscordWebhook extends BaseChannel {
    public DiscordWebhook(String target) {
        super("DISCORD", target);
    }
    @Override
    protected void deliver(String message) {
        System.out.println("[Webhook " + target + "] Embed: " + message);
    }
}

public class OmnichannelApp {
    public static void main(String[] args) {
        BaseChannel[] channels = new BaseChannel[] {
            new SmsNotification("+15551234"),
            new DiscordWebhook("#incident-room")
        };
        String alert = "Production server 502 error resolved";
        for (BaseChannel ch : channels) {
            ch.broadcast(alert);
        }
    }
}
